    ifstream in("herding.in");
    ofstream out("herding.out");
    array<long long, 3> positions;
    for (long long &position : positions) in >> position;
    sort(positions.begin(), positions.end());
    long long a = positions[1] - positions[0], b = positions[2] - positions[1];
    int minimum = 2;
    if (a == 1 && b == 1) minimum = 0;
    else if (a == 2 || b == 2) minimum = 1;
    out << minimum << '\n' << max(a, b) - 1 << '\n';
}
