#include <fstream>
#include <vector>
using namespace std;
int main() {
    ifstream in("revegetate.in");
    ofstream out("revegetate.out");
    int n, m;
    in >> n >> m;
    vector<vector<int>> neighbors(n);
    for (int i = 0; i < m; ++i) {
        int a, b;
        in >> a >> b;
        --a; --b;
        neighbors[a].push_back(b);
        neighbors[b].push_back(a);
    }
    vector<int> colors(n, 0);
    for (int pasture = 0; pasture < n; ++pasture) {
        bool forbidden[5] = {};
        for (int other : neighbors[pasture]) forbidden[colors[other]] = true;
        for (int color = 1; color <= 4; ++color) {
            if (!forbidden[color]) { colors[pasture] = color; break; }
        }
        out << colors[pasture];
    }
    out << '\n';
}
