#include <algorithm>
#include <fstream>
#include <string>
#include <utility>
#include <vector>
using namespace std;
struct Segment { string kind; int low, high; };
pair<int, int> sweep(const vector<Segment> &segments, bool reverse) {
    int n = static_cast<int>(segments.size());
    int low = 0, high = 1000 * (n + 1);
    for (int step = 0; step < n; ++step) {
        int index = reverse ? n - 1 - step : step;
        const Segment &segment = segments[index];
        if (segment.kind == "none") {
            low = max(low, segment.low);
            high = min(high, segment.high);
        } else {
            bool adds = (segment.kind == "on") != reverse;
            if (adds) {
                low += segment.low;
                high += segment.high;
            } else {
                low = max(0, low - segment.high);
                high -= segment.low;
            }
        }
    }
    return {low, high};
}
int main() {
    ifstream in("traffic.in");
    ofstream out("traffic.out");
    int n;
    in >> n;
    vector<Segment> segments(n);
    for (Segment &segment : segments) in >> segment.kind >> segment.low >> segment.high;
    auto before = sweep(segments, true), after = sweep(segments, false);
    out << before.first << ' ' << before.second << '\n';
    out << after.first << ' ' << after.second << '\n';
}
